Complete the comprehensive test example:

```dart
group('%order% Calculator Tests', () {
  Calculator? calculator;

  %order%(() {
    calculator = Calculator();
  });

  group('Addition', () {
    %order%('should return sum of two positive numbers', () {
      expect(calculator!.add(2, 3), %order%(5));
    });

    %order%('should handle zero addition', () {
      expect(calculator!.add(0, 5), %order%(5));
    });

    %order%('should handle negative numbers', () {
      expect(calculator!.add(-2, 3), %order%(1));
    });
  });

  group('Division', () {
    %order%('should throw error on division by zero', () {
      expect(() => calculator!.divide(10, 0), %order%);
    });
  });
});
```
